-- Verification Block
DO $$
DECLARE
  config_count integer;
  calendar_count integer;
  available_next_month_count integer;
BEGIN
  SELECT COUNT(*) INTO config_count FROM public.inventory_configs WHERE is_active = true;
  SELECT COUNT(*) INTO calendar_count FROM public.inventory_calendars WHERE date >= '2026-06-04'::date AND date < ('2026-06-04'::date + INTERVAL '90 days');
  SELECT COUNT(DISTINCT listing_id) INTO available_next_month_count FROM public.inventory_calendars WHERE status = 'AVAILABLE' AND available_quantity > 0 AND date >= ('2026-06-04'::date + INTERVAL '30 days') AND date < ('2026-06-04'::date + INTERVAL '60 days');
  IF config_count < 220 THEN
    RAISE EXCEPTION 'Inventory seed verification failed: only % active configs', config_count;
  END IF;
  IF calendar_count < 19800 THEN
    RAISE EXCEPTION 'Inventory seed verification failed: only % calendar rows', calendar_count;
  END IF;
  IF available_next_month_count < 176 THEN
    RAISE EXCEPTION 'Inventory seed verification failed: only % listings available next month', available_next_month_count;
  END IF;
  RAISE NOTICE 'Inventory seed verification passed: configs=%, calendars=%, available next month=%', config_count, calendar_count, available_next_month_count;
END $$;
